package fetvisuals.modules.effects;
import fetvisuals.module.*; import fetvisuals.module.settings.*; import fetvisuals.render.RenderUtils; import net.minecraft.client.MinecraftClient; import net.minecraft.client.gui.DrawContext;
public final class DamageVignette extends fetvisuals.module.Module {private final NumberSetting duration=add(new NumberSetting("Duration",350,50,1000,10));public DamageVignette(){super("DamageVignette","Screen edge flash after damage",Category.EFFECTS);}public void onHud(DrawContext c,float d){MinecraftClient mc=MinecraftClient.getInstance();if(mc.player==null||mc.player.hurtTime<=0)return;float p=Math.min(1,mc.player.hurtTime/10f);int a=(int)(120*p);int col=RenderUtils.alpha(0xFF4A2B6B,a);int w=mc.getWindow().getScaledWidth(),h=mc.getWindow().getScaledHeight();RenderUtils.rect(c,0,0,w,7,col);RenderUtils.rect(c,0,h-7,w,7,col);RenderUtils.rect(c,0,0,7,h,col);RenderUtils.rect(c,w-7,0,7,h,col);}}
